test_that("standardization retains template geometry and mask", { r<-terra::rast(nrows=4,ncols=4,xmin=0,xmax=4,ymin=0,ymax=4,crs="EPSG:4326"); terra::values(r)<-280; t<-r; v<-terra::values(t); v[c(1,4)]<-NA; terra::values(t)<-v; z<-standardize_daily_raster(r,t); expect_true(terra::compareGeom(z,t,stopOnError=FALSE)); expect_true(all(is.na(terra::values(z))[c(1,4)])); expect_equal(terra::values(z)[2],280) })
